import { getAuth,onAuthStateChanged,createUserWithEmailAndPassword,signInWithEmailAndPassword,signOut,updateProfile,getIdTokenResult,sendEmailVerification } from "https://www.gstatic.com/firebasejs/12.5.0/firebase-auth.js";
import { getFirestore,doc,getDoc,setDoc,updateDoc,addDoc,collection,getDocs,query,where,orderBy,limit,serverTimestamp } from "https://www.gstatic.com/firebasejs/12.5.0/firebase-firestore.js";
import { getStorage,ref as storageRef,uploadBytes,getDownloadURL } from "https://www.gstatic.com/firebasejs/12.5.0/firebase-storage.js";
import { getFunctions,httpsCallable } from "https://www.gstatic.com/firebasejs/12.5.0/firebase-functions.js";
import { firebaseConfig } from "./firebase-config.js";

const app=initializeApp(firebaseConfig),auth=getAuth(app),db=getFirestore(app),storage=getStorage(app),functions=getFunctions(app,"us-east1");
const FOUNDER_EMAIL="avengers_0077@hotmail.com";
const ROLES=["Jugador","Entrenador","Árbitro","Preparador físico","Entrenador de porteros","Directivo","Administrador de club","Organizador deportivo","Aficionado"];
const state={user:null,profile:{},claims:{},page:"Inicio",theme:localStorage.getItem("cascarita-theme")||"dark",leagues:[],selectedLeague:"",admin:false,pendingInitialRole:"",activeMode:localStorage.getItem("cascarita-active-mode")||"public",managerSection:localStorage.getItem("cascarita-manager-section")||"overview"};
const root=document.getElementById("app");
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const initials=n=>String(n||"C").trim().split(/\s+/).slice(0,2).map(x=>x[0]||"").join("").toUpperCase();
function toast(msg,type="info"){const host=document.getElementById("toast-root"),el=document.createElement("div");el.className=`toast ${type}`;el.textContent=msg;host.append(el);setTimeout(()=>el.classList.add("show"),10);setTimeout(()=>el.remove(),3600)}
function theme(){document.documentElement.dataset.theme=state.theme;localStorage.setItem("cascarita-theme",state.theme)}theme();
const roleList=()=>Array.isArray(state.profile.roles)?state.profile.roles:["Aficionado"];
const isAdmin=()=>state.admin;
function authView(){const reg=state.authMode==="register";root.innerHTML=`<main class="auth-layout"><section class="auth-art"><div class="auth-brand"><div class="brand-mark">⚽</div><div><b>CASCARITA</b><small>DONDE COMIENZA TU HISTORIA</small></div></div><div class="art-copy"><div class="eyebrow"><i></i> EL FÚTBOL NOS UNE</div><h1>Tu historia<br><em>comienza</em><br>en la cancha.</h1><p>Noticias, ligas, equipos y talento. Todo el fútbol de nuestra comunidad en un solo lugar.</p><div class="art-motto"><span>DEL BARRIO A LA CANCHA.</span><span>DE LA PASIÓN AL PROGRESO.</span></div></div><div class="giant-ball">⚽</div><div class="art-foot">CASCARITA · FÚTBOL CON FUTURO</div></section><section class="auth-side"><div class="auth-card"><div class="eyebrow green">${reg?"ÚNETE A LA COMUNIDAD":"BIENVENIDO DE NUEVO"}</div><h2>${reg?"Crea tu cuenta.":"Inicia sesión."}</h2><p class="sub">${reg?"Todos comienzan como aficionados. Tu camino puede crecer.":"Entra para seguir tu fútbol."}</p><div id="auth-error" class="form-error" hidden></div><form id="auth-form">${reg?'<label>Nombre completo<input name="name" required minlength="2" maxlength="90"></label><label>Rol inicial<select name="initialRole">'+ROLES.map(r=>'<option value="'+r+'">'+r+'</option>').join('')+'</select><small>Durante las pruebas puedes elegir un perfil deportivo. Los permisos administrativos siguen protegidos.</small></label>':''}<label>Correo electrónico<input name="email" type="email" required></label><label>Contraseña<input name="password" type="password" minlength="6" required></label><button class="btn-primary full">${reg?"Crear cuenta":"Entrar"} →</button></form><div class="auth-switch">${reg?"¿Ya tienes cuenta?":"¿Aún no tienes cuenta?"} <button id="switch-auth">${reg?"Inicia sesión":"Regístrate"}</button></div></div></section></main>`;
 document.getElementById("switch-auth").onclick=()=>{state.authMode=reg?"login":"register";authView()};document.getElementById("auth-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),email=String(f.get("email")).trim().toLowerCase(),password=String(f.get("password")),name=String(f.get("name")||"").trim(),b=e.currentTarget.querySelector("button");b.disabled=true;try{let cred;if(reg){state.pendingInitialRole=String(f.get("initialRole")||"Aficionado");cred=await createUserWithEmailAndPassword(auth,email,password);await updateProfile(cred.user,{displayName:name});const initialRole=state.pendingInitialRole||"Aficionado";await setDoc(doc(db,"users",cred.user.uid),{displayName:name,email,roles:[ROLES.includes(initialRole)?initialRole:"Aficionado"],status:"active",createdAt:serverTimestamp(),updatedAt:serverTimestamp()});state.pendingInitialRole="";toast("Cuenta creada. Ya puedes entrar a CASCARITA.");}else cred=await signInWithEmailAndPassword(auth,email,password);}catch(err){document.getElementById("auth-error").hidden=false;document.getElementById("auth-error").textContent=err.message;}finally{b.disabled=false}}}
function navItems(){
 const mode=state.activeMode||"public";
 if(mode==="admin")return [["Administración","⚙"]];
 if(mode==="manager")return [["Modo manager","⚽"]];
 if(mode==="player")return [["Modo jugador","♟"]];
 return [["Inicio","⌂"],["Competiciones","🏆"],["Clubes","⬟"],["Jugadores","♟"],["Mi perfil","♙"]];
}
function shell(){const items=navItems(),name=state.profile.displayName||state.user.displayName||"Aficionado",current=items.find(x=>x[0]===state.page)||items[0];root.innerHTML=`<div class="app-shell ${state.activeMode==='manager'?'mode-manager':state.activeMode==='player'?'mode-player':state.activeMode==='admin'?'mode-admin':'mode-public'}"><aside class="sidebar"><div class="sidebar-brand"><div class="brand-mark">⚽</div><div><b>CASCARITA</b><small>FÚTBOL CON FUTURO</small></div></div><div class="side-caption">COMUNIDAD DE FÚTBOL</div><div class="nav-caption">EXPLORAR</div><nav>${state.activeMode==="manager"?`<div class="pes-nav-group"><small>MI EQUIPO</small>${[["overview","Vista general"],["team","Mi equipo"],["strategy","Estrategia"],["squad","Lista de jugadores"],["training","Entrenamientos"],["stats","Estadísticas de partidos"]].map(([k,n])=>`<button class="nav-item ${state.managerSection===k?"active":""}" data-manager-section="${k}">${n}</button>`).join("")}<small>AVANZAR EN EL TIEMPO</small><button class="nav-item ${state.managerSection==="calendar"?"active":""}" data-manager-section="calendar">Avanzar en el tiempo</button><small>INFORMACIÓN</small>${[["gazette","Gaceta"],["league-calendar","Calendario de liga"],["league-teams","Equipos de la liga"],["tournament","Información del torneo"],["records","Registros"]].map(([k,n])=>`<button class="nav-item ${state.managerSection===k?"active":""}" data-manager-section="${k}">${n}</button>`).join("")}<small>NEGOCIACIONES</small>${[["prospects","Prospectos"],["favorites","Favoritos"],["affiliate","Equipo filial"],["negotiations","En negociaciones"],["search-players","Búsqueda avanzada"],["transfer-news","Noticias de fichajes"]].map(([k,n])=>`<button class="nav-item ${state.managerSection===k?"active":""}" data-manager-section="${k}">${n}</button>`).join("")}</div>`:items.map(([n,i])=>`<button class="nav-item ${state.page===n?"active":""}" data-page="${n}"><span class="nav-symbol">${i}</span>${n}</button>`).join("")}</nav><div class="side-bottom"><div class="help-card"><b>Donde comienza tu historia</b><span>El fútbol nos conecta.</span></div><div class="account-row"><div class="avatar">${state.profile.photoURL?`<img src="${esc(state.profile.photoURL)}">`:initials(name)}</div><div class="account-text"><b>${esc(name)}</b><small>${esc(state.user.email)}</small></div><button id="logout" class="logout">↗</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb">CASCARITA <span>/</span> <b>${current[0]}</b></div><div class="top-actions"><div class="role-indicator"><span>${state.activeMode==="admin"?"SUPERADMINISTRADOR":state.activeMode==="manager"?"DIRECTIVO":state.activeMode==="player"?"JUGADOR":esc(roleList()[0]||"AFICIONADO")}</span></div><button class="round-btn" id="theme-toggle">${state.theme==="dark"?"☀":"☾"}</button><div class="top-avatar">${state.profile.photoURL?`<img src="${esc(state.profile.photoURL)}">`:initials(name)}</div></div></header><div class="page"><div class="page-heading"><div><div class="eyebrow green">${state.activeMode==="admin"?"ADMINISTRACIÓN CENTRAL":state.activeMode==="manager"?"GESTIÓN DE CLUB":state.activeMode==="player"?"CARRERA DEPORTIVA":"FÚTBOL CON FUTURO"}</div><h1>${current[0]==="Inicio"?`Hola, ${esc(name.split(" ")[0])}`:current[0]}</h1><p>${current[0]==="Inicio"?"Sigue tus ligas, descubre partidos y vive el fútbol de tu comunidad.":"Tu espacio en CASCARITA."}</p></div><div class="season">● ${state.activeMode==="admin"?"SUPERADMINISTRADOR":state.activeMode==="manager"?"DIRECTIVO":state.activeMode==="player"?"JUGADOR":esc(roleList()[0]||"AFICIONADO")}</div></div><div id="page-content"></div><footer class="footer">© 2026 CASCARITA · DONDE COMIENZA TU HISTORIA</footer></div></main></div>`;
 root.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>{state.page=b.dataset.page;renderPage()});document.getElementById("logout").onclick=()=>signOut(auth);document.getElementById("theme-toggle").onclick=()=>{state.theme=state.theme==="dark"?"light":"dark";theme();shell();renderPage()};renderPage()}
function renderPage(){const host=document.getElementById("page-content");if(!host)return;host.innerHTML='<div class="muted">Cargando...</div>';({Inicio:homePage,Competiciones:leaguesPage,Clubes:clubsPage,Jugadores:playersPage,"Mi perfil":profilePage,"Mis paneles":panelsPage,"Modo manager":managerPage,"Modo jugador":playerCareerPage,Administración:adminPage}[state.page]||homePage)().then(html=>{if(document.getElementById("page-content"))document.getElementById("page-content").innerHTML=html;bindPage()}).catch(e=>{console.error(e);host.innerHTML='<div class="panel">No fue posible cargar esta sección. Revisa tu conexión y los permisos de Firebase.</div>'})}
async function loadLeagues(){const s=await getDocs(query(collection(db,"leagues"),where("status","in",["active","registration"])));state.leagues=s.docs.map(d=>({id:d.id,...d.data()}));if(!state.selectedLeague&&state.leagues.length)state.selectedLeague=state.leagues[0].id;return state.leagues}
async function homePage(){const leagues=await loadLeagues();let news=[];try{const s=await getDocs(query(collection(db,"news"),where("published","==",true),limit(5)));news=s.docs.map(d=>d.data())}catch{}return `${String(state.user.email||"").toLowerCase()===FOUNDER_EMAIL&&!isAdmin()?`<section class="panel founder-setup"><div><div class="eyebrow green">CUENTA FUNDADORA</div><h3>${state.user.emailVerified?"Activa tu administración central":"Verifica tu correo para activar la administración"}</h3><p>El permiso se asigna desde Firebase y solo a la cuenta fundadora verificada.</p></div>${state.user.emailVerified?`<button class="btn-primary" id="claim-founder">Activar superadministrador →</button>`:`<button class="btn-primary" id="send-verify">Enviar verificación →</button>`}</section>`:""}<section class="public-hero"><div><div class="eyebrow green">EL FÚTBOL DE TODOS</div><h2>La pasión de tu comunidad,<br><em>en una sola cancha.</em></h2><p>Encuentra tu liga, sigue a tus equipos y no te pierdas ningún encuentro.</p><button class="btn-primary" data-go="Competiciones">Explorar competiciones →</button></div><div class="hero-ball">⚽</div></section><section class="panel"><div class="panel-head"><div><div class="eyebrow green">ELIGE QUÉ QUIERES SEGUIR</div><h3>Competiciones activas</h3></div><span class="panel-icon">🏆</span></div>${leagues.length?`<div class="league-grid">${leagues.map(l=>`<article class="league-card"><span class="league-tag">${esc(l.branch||"Fútbol 11")}</span><h3>${esc(l.name)}</h3><p>${esc(l.city||"")} · ${esc(l.season||"Temporada actual")}</p><button class="btn-secondary" data-league="${l.id}">Ver competición →</button></article>`).join("")}</div>`:'<div class="empty-state">Todavía no hay competiciones activas. Pronto podrás seguir aquí las ligas de tu comunidad.</div>'}</section><section class="panel"><div class="panel-head"><div><div class="eyebrow green">ACTUALIDAD</div><h3>Noticias y comunicados</h3></div></div>${news.length?news.map(n=>`<article class="news-row"><b>${esc(n.title)}</b><p>${esc(n.body||"")}</p></article>`).join(""):'<div class="empty-state">Las noticias oficiales aparecerán aquí cuando las organizaciones publiquen información.</div>'}</section>`}
async function leaguesPage(){const ls=await loadLeagues();return `<section class="panel"><div class="panel-head"><div><div class="eyebrow green">TEMPORADAS Y TORNEOS</div><h3>Todas las competiciones activas</h3></div></div>${ls.length?`<div class="league-grid">${ls.map(l=>`<article class="league-card"><span class="league-tag">${esc(l.branch||"Fútbol 11")}</span><h3>${esc(l.name)}</h3><p>${esc(l.city||"")} · ${esc(l.season||"")}</p><button class="btn-secondary" data-league="${l.id}">Consultar liga →</button></article>`).join("")}</div>`:'<div class="empty-state">No hay ligas activas todavía.</div>'}</section><div id="league-detail"></div>`}
async function clubsPage(){const s=await getDocs(query(collection(db,"teams"),where("status","==","active"),limit(50)));return `<section class="panel"><div class="panel-head"><div><div class="eyebrow green">EQUIPOS REGISTRADOS</div><h3>Clubes y equipos</h3></div></div>${s.empty?'<div class="empty-state">Los equipos aparecerán aquí cuando una liga los registre.</div>':`<div class="league-grid">${s.docs.map(d=>{const x=d.data();return `<article class="league-card"><h3>${esc(x.name)}</h3><p>${esc(x.branch||"")} · ${esc(x.city||"")}</p><small>${esc(x.leagueName||"")}</small></article>`}).join("")}</div>`}</section>`}
async function playersPage(){const s=await getDocs(query(collection(db,"players"),where("visibility","==","public"),limit(40)));return `<section class="panel"><div class="panel-head"><div><div class="eyebrow green">TALENTO DE LA COMUNIDAD</div><h3>Directorio de jugadores</h3></div></div>${s.empty?'<div class="empty-state">Los jugadores que habiliten su perfil público aparecerán aquí.</div>':`<div class="league-grid">${s.docs.map(d=>{const x=d.data();return `<article class="league-card"><h3>${esc(x.displayName||"Jugador")}</h3><p>${esc(x.position||"Posición por definir")} · ${esc(x.city||"")}</p></article>`}).join("")}</div>`}</section>`}
async function profilePage(){const p=state.profile,u=state.user;return `<section class="panel form-panel"><div class="panel-head"><div><div class="eyebrow green">TU IDENTIDAD</div><h3>Mi perfil</h3></div></div><form id="profile-form" class="data-form"><div class="photo-uploader"><div class="profile-photo">${p.photoURL?`<img src="${esc(p.photoURL)}">`:initials(p.displayName||u.displayName||u.email)}</div><div><b>Fotografía de perfil</b><p>JPG, PNG o WEBP · máximo 5 MB</p><input type="file" id="profile-photo" accept="image/jpeg,image/png,image/webp"></div></div><label>Nombre completo<input name="displayName" required maxlength="90" value="${esc(p.displayName||u.displayName||"")}"></label><label>Correo<input disabled value="${esc(u.email)}"></label><label>Teléfono<input name="phone" value="${esc(p.phone||"")}" maxlength="25"></label><label>Municipio / ciudad<input name="city" value="${esc(p.city||"")}" maxlength="80"></label><label class="wide">Presentación<textarea name="bio" rows="3" maxlength="500">${esc(p.bio||"")}</textarea></label>${roleList().includes("Jugador")?`<label>Posición de juego<input name="playerPosition" value="${esc(p.playerPosition||"")}" placeholder="Portero, defensa, medio, delantero"></label><label>Perfil de jugador<select name="playerVisibility"><option value="public" ${(p.playerVisibility||"public")==="public"?"selected":""}>Visible para buscar equipo</option><option value="private" ${p.playerVisibility==="private"?"selected":""}>Privado</option></select></label>`:""}<div class="wide form-actions"><button class="btn-primary">Guardar perfil</button></div></form></section>`}
async function panelsPage(){const roles=roleList().filter(r=>r!=="Aficionado"),leagues=await loadLeagues(),canCreate=roles.some(r=>["Directivo","Administrador de club"].includes(r));return `<section class="panel"><div class="panel-head"><div><div class="eyebrow green">TUS HERRAMIENTAS</div><h3>Paneles disponibles</h3></div></div>${roles.length?`<div class="role-panel-grid">${roles.map(r=>`<article class="league-card"><span class="panel-icon">${r==="Jugador"?"♟":r==="Árbitro"?"⚑":"▣"}</span><h3>${esc(r)}</h3><p>Herramientas y funciones de tu perfil ${esc(r.toLowerCase())}.</p><button class="btn-secondary" data-role-panel="${esc(r)}">Abrir panel →</button></article>`).join("")}</div>`:'<div class="empty-state">Todavía no tienes roles deportivos adicionales. Desde Mi perfil puedes solicitar uno. Mientras tanto puedes seguir explorando todas las competiciones como aficionado.</div>'}<div id="role-panel-detail"></div></section>${canCreate?`<section class="panel form-panel"><div class="eyebrow green">REGISTRO DE EQUIPO</div><h3>Solicitar participación en una competición</h3><p>Registra los datos de tu equipo. La administración revisará la solicitud antes de incorporarlo oficialmente.</p><form id="team-request-form" class="data-form"><label>Nombre del equipo<input name="teamName" required maxlength="100"></label><label>Competición<select name="leagueId" required>${leagues.filter(l=>['registration','active'].includes(l.status)).map(l=>`<option value="${l.id}">${esc(l.name)} · ${esc(l.season||'')}</option>`).join('')}</select></label><label>Nombre del club<input name="clubName" value="${esc(state.profile.clubName||'')}" required maxlength="100"></label><label>Municipio<input name="city" value="${esc(state.profile.city||'')}" required maxlength="80"></label><label>Rama<select name="branch"><option>Varonil</option><option>Femenil</option><option>Juvenil</option></select></label><label>Categoría<input name="category" placeholder="Libre, Sub-17..."></label><div class="wide"><button class="btn-primary" ${leagues.filter(l=>['registration','active'].includes(l.status)).length?'':'disabled'}>Enviar solicitud de equipo →</button></div></form></section>`:''}`}

async function adminPage(){
 if(!isAdmin())return '<div class="panel">No tienes autorización para acceder.</div>';
 const [us,ls,ts,roles,teamReq,clubReq,orgReq]=await Promise.all([
  getDocs(query(collection(db,"users"),limit(250))),getDocs(query(collection(db,"leagues"),limit(150))),getDocs(query(collection(db,"teams"),limit(250))),
  getDocs(query(collection(db,"roleRequests"),where("status","==","pending"),limit(100))),
  getDocs(query(collection(db,"teamRequests"),where("status","==","pending"),limit(100))),
  getDocs(query(collection(db,"clubRequests"),where("status","==","pending"),limit(100))),
  getDocs(query(collection(db,"organizationRequests"),where("status","==","pending"),limit(100)))
 ]);
 const leagueRows=ls.docs.map(d=>{const x=d.data();return `<div class="history-row"><div><b>${esc(x.name)}</b><small>${esc(x.season||'')} · ${esc(x.city||'')} · ${esc(x.status||'draft')} · ${esc(x.branch||'')}</small></div><div class="admin-actions"><button class="btn-secondary" data-edit-league="${d.id}">Editar</button><button class="btn-secondary" data-league-status="${d.id}" data-status="${x.status==='active'?'paused':x.status==='paused'?'active':x.status==='finished'?'archived':'active'}">${x.status==='active'?'Pausar':x.status==='paused'?'Reactivar':x.status==='finished'?'Archivar':'Activar'}</button><button class="btn-secondary" data-fixtures="${d.id}">Generar calendario</button>${x.status==='active'||x.status==='paused'?`<button class="btn-secondary" data-league-status="${d.id}" data-status="finished">Finalizar</button>`:''}<button class="btn-danger" data-delete-league="${d.id}">Eliminar</button></div></div>`}).join('');
 const requestRows=teamReq.docs.map(d=>{const x=d.data();return `<div class="history-row"><div><b>${esc(x.teamName||x.name||'Equipo solicitado')}</b><small>${esc(x.clubName||x.requesterName||x.email||'')} · ${esc(x.leagueName||x.leagueId||'')} · ${esc(x.branch||'')} ${esc(x.category||'')}</small></div><div class="admin-actions"><button class="btn-primary" data-team-approve="${d.id}">Aprobar equipo</button><button class="btn-secondary" data-team-reject="${d.id}">Rechazar</button></div></div>`}).join('');
 const userRows=us.docs.map(d=>{const x=d.data(),status=x.status||'active';return `<div class="history-row"><div><b>${esc(x.displayName||'Sin nombre')}</b><small>${esc(x.email||d.id)} · ${esc((x.roles||['Aficionado']).join(', '))} · ${esc(status)}</small></div><div class="admin-actions"><button class="btn-secondary" data-user-status="${d.id}" data-status="${status==='active'?'suspended':'active'}">${status==='active'?'Suspender':'Reactivar'}</button>${status!=='deactivated'?`<button class="btn-danger" data-user-status="${d.id}" data-status="deactivated">Dar de baja</button>`:''}</div></div>`}).join('');
 const roleRows=roles.docs.map(d=>{const x=d.data();return `<div class="history-row"><div><b>${esc(x.role)}</b><small>${esc(x.name||'')} · ${esc(x.email||'')}</small></div><button class="btn-primary" data-approve-role="${d.id}">Aprobar</button></div>`}).join('');
 return `<section class="panel"><div class="eyebrow green">CENTRO DE CONTROL</div><h3>Administración central</h3><p>Gestiona usuarios, organizaciones, equipos y competiciones desde un solo lugar.</p></section>
 <section class="stats"><article class="stat"><small>Usuarios</small><strong>${us.size}</strong></article><article class="stat"><small>Competiciones</small><strong>${ls.size}</strong></article><article class="stat"><small>Equipos</small><strong>${ts.size}</strong></article><article class="stat"><small>Solicitudes pendientes</small><strong>${roles.size+teamReq.size+clubReq.size+orgReq.size}</strong></article></section>
 <section class="panel form-panel"><div class="panel-head"><div><div class="eyebrow green">CONFIGURACIÓN DEPORTIVA</div><h3 id="league-form-title">Crear competición</h3></div></div><form id="league-form" class="data-form"><input type="hidden" name="leagueId"><label>Nombre<input name="name" required maxlength="100" placeholder="Liga Municipal"></label><label>Temporada<input name="season" required placeholder="2026-2027"></label><label>Municipio / cobertura<input name="city" required></label><label>Rama<select name="branch"><option>Varonil</option><option>Femenil</option><option>Juvenil</option><option>Mixta / formativa</option></select></label><label>Categoría<input name="category" placeholder="Libre, Sub-17, Sub-20..."></label><label>Modalidad<select name="modality"><option value="Fútbol 11">Fútbol 11</option></select></label><label>Formato<select name="format"><option value="round_robin">Todos contra todos</option></select></label><label>Cupo máximo<input name="teamLimit" type="number" min="2" max="64" value="16" required></label><label>Vueltas<select name="legs"><option value="1">Una vuelta</option><option value="2" selected>Ida y vuelta</option></select></label><label>Estado<select name="status"><option value="draft">En preparación</option><option value="registration">Inscripciones abiertas</option><option value="active">Activa</option><option value="paused">Pausada</option></select></label><label>Puntos por victoria<input name="pointsWin" type="number" min="0" max="10" value="3"></label><label>Puntos por empate<input name="pointsDraw" type="number" min="0" max="10" value="1"></label><label>Puntos por derrota<input name="pointsLoss" type="number" min="0" max="10" value="0"></label><label class="wide">Criterios de desempate<input name="tieBreakers" value="Puntos, diferencia de goles, goles a favor" maxlength="180"></label><div class="wide"><button class="btn-primary">Guardar competición →</button> <button type="button" class="btn-secondary" id="league-form-reset">Limpiar</button></div></form></section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">COMPETICIONES</div><h3>Administrar ligas y torneos</h3></div></div>${leagueRows||'<div class="empty-state">Aún no hay competiciones.</div>'}</section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">SOLICITUDES DE EQUIPOS</div><h3>Equipos que desean participar</h3></div></div>${requestRows||'<div class="empty-state">No hay solicitudes pendientes de equipos. Los equipos deberán solicitar su incorporación a una competición.</div>'}</section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">SOLICITUDES DE CLUBES Y ORGANIZACIONES</div><h3>Revisión institucional</h3></div></div>${[...clubReq.docs.map(d=>({id:d.id,x:d.data(),type:'club'})),...orgReq.docs.map(d=>({id:d.id,x:d.data(),type:'organization'}))].map(r=>`<div class="history-row"><div><b>${esc(r.x.name||r.x.clubName||r.x.organizationName||r.type)}</b><small>${esc(r.x.email||r.x.uid||'')} · ${r.type==='club'?'Club':'Organización deportiva'}</small></div><button class="btn-secondary" data-generic-request="${r.id}" data-kind="${r.type}">Revisar</button></div>`).join('')||'<div class="empty-state">No hay solicitudes institucionales pendientes.</div>'}</section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">DIRECTORIO</div><h3>Usuarios y acceso</h3></div></div><input id="user-search" placeholder="Buscar por nombre o correo..."> <div id="user-directory">${userRows||'<div class="empty-state">Sin usuarios.</div>'}</div></section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">PERFILES Y PERMISOS</div><h3>Solicitudes de roles</h3></div></div>${roleRows||'<div class="empty-state">No hay solicitudes pendientes.</div>'}</section>
 <section class="panel form-panel"><div class="panel-head"><div><div class="eyebrow green">COMUNICACIÓN OFICIAL</div><h3>Publicar noticia</h3></div></div><form id="news-form" class="data-form"><label>Titular<input name="title" required maxlength="120"></label><label class="wide">Contenido<textarea name="body" rows="3" required maxlength="2000"></textarea></label><div class="wide"><button class="btn-primary">Publicar noticia →</button></div></form></section>`;
}
async function managerPage(){
 await loadLeagues();
 const section=state.managerSection||"overview";
 const own=await getDocs(query(collection(db,"teams"),where("managerUid","==",state.user.uid),limit(50))).catch(()=>getDocs(query(collection(db,"teams"),where("createdBy","==",state.user.uid),limit(50))));
 const teams=own.docs.map(d=>({id:d.id,...d.data()}));
 const selected=teams.find(t=>t.id===state.selectedManagerTeam)||teams[0];
 if(selected)state.selectedManagerTeam=selected.id;
 let roster={docs:[]},league=null,matches={docs:[]},transfers={docs:[]},players={docs:[]};
 if(selected){roster=await getDocs(collection(db,"teams",selected.id,"roster")).catch(()=>({docs:[]}));if(selected.leagueId){league=await getDoc(doc(db,"leagues",selected.leagueId)).catch(()=>null);matches=await getDocs(query(collection(db,"matches"),where("leagueId","==",selected.leagueId),limit(100))).catch(()=>({docs:[]}));}}
 transfers=await getDocs(query(collection(db,"transferRequests"),where("managerUid","==",state.user.uid),limit(100))).catch(()=>({docs:[]}));
 players=await getDocs(query(collection(db,"players"),where("visibility","==","public"),limit(100))).catch(()=>({docs:[]}));
 const pending=transfers.docs.filter(d=>d.data().status==="pending");
 const crest=selected?.crestURL?`<img src="${esc(selected.crestURL)}" alt="Escudo">`:`<span>⚽</span>`;
 const teamSelect=teams.length?`<select id="manager-team-select">${teams.map(t=>`<option value="${t.id}" ${selected?.id===t.id?"selected":""}>${esc(t.name)}</option>`).join("")}</select>`:"";
 const upcoming=matches.docs.map(d=>({id:d.id,...d.data()})).filter(m=>m.status!=="final").slice(0,4);
 const rosterRows=roster.docs.map(d=>{const x=d.data();return `<div class="pes-player-row"><b>${esc(x.number||"—")}</b><span>${esc(x.position||"POS")}</span><strong>${esc(x.displayName||x.email||"Jugador")}</strong><small>${esc(x.status||"Activo")}</small></div>`}).join("");
 const requestRows=pending.map(d=>{const x=d.data();return `<div class="pes-list-row"><div><b>${esc(x.playerName||"Jugador")}</b><small>${esc(x.position||"Posición por definir")} · ${esc(x.playerEmail||"")}</small></div><div class="inline-actions"><button class="btn-approve" data-transfer-approve="${d.id}">Aceptar</button><button class="btn-reject" data-transfer-reject="${d.id}">Rechazar</button></div></div>`}).join("");
 const title=({overview:"Vista general",team:"Mi equipo",strategy:"Estrategia",squad:"Lista de jugadores",training:"Entrenamientos",stats:"Estadísticas de partidos",calendar:"Avanzar en el tiempo",gazette:"Gaceta", "league-calendar":"Calendario de liga","league-teams":"Equipos de la liga",tournament:"Información del torneo",records:"Registros",prospects:"Prospectos",favorites:"Favoritos",affiliate:"Equipo filial",negotiations:"En negociaciones","search-players":"Búsqueda avanzada de jugadores","transfer-news":"Noticias sobre fichajes"})[section]||"Vista general";
 let body="";
 if(section==="overview"){
  body=`<div class="pes-overview-grid"><section class="pes-stadium-card"><div class="pes-stadium-overlay"><div class="pes-date">${new Date().toLocaleDateString("es-MX",{day:"2-digit",month:"long",year:"numeric"})}</div><div class="pes-club-identity">${crest}<div><small>${esc(league?.exists()?league.data().name:(selected?.leagueName||"SIN COMPETICIÓN"))}</small><h2>${esc(selected?.name||"TU CLUB")}</h2><span>${esc(selected?.city||state.profile.city||"Municipio por definir")} · ${esc(selected?.season||"Temporada")}</span></div></div><div class="pes-sponsor-strip"><span>PATROCINADOR PRINCIPAL</span>${selected?.sponsorLogoURL?`<img src="${esc(selected.sponsorLogoURL)}" alt="Patrocinador">`:""}<b>${esc(selected?.sponsorName||"PATROCINADOR DEL CLUB")}</b><span>${esc(selected?.secondarySponsor||"CASA DEPORTIVA")}</span></div><div class="pes-next-match"><small>PRÓXIMO ENCUENTRO</small>${upcoming[0]?`<div class="pes-match-line"><div class="pes-match-club">${selected?.crestURL?`<img src="${esc(selected.crestURL)}" alt="">`:`<i>⚽</i>`}<b>${esc(selected?.name||"MI EQUIPO")}</b></div><span>VS</span><div class="pes-match-club">${(upcoming[0].awayTeamCrestURL||upcoming[0].homeTeamCrestURL)?`<img src="${esc(upcoming[0].awayTeamCrestURL||upcoming[0].homeTeamCrestURL)}" alt="">`:`<i>⚽</i>`}<b>${esc(upcoming[0].awayTeam||upcoming[0].homeTeam||"RIVAL POR DEFINIR")}</b></div></div><p>${upcoming[0].kickoff?.toDate?upcoming[0].kickoff.toDate().toLocaleString("es-MX"):"Fecha y horario por confirmar"}</p>`:`<div class="pes-match-line"><b>${esc(selected?.name||"MI EQUIPO")}</b><span>VS</span><b>RIVAL POR DEFINIR</b></div><p>Próximo partido pendiente de calendario</p>`}</div></div></section><aside class="pes-overview-side"><div class="pes-mini-card"><small>MI EQUIPO</small><h3>${esc(selected?.name||"Aún no tienes equipo")}</h3><p>${selected?`${roster.size||roster.docs.length} jugadores registrados · ${esc(selected.branch||"Fútbol 11")}`:"Registra tu primer equipo y comienza la temporada."}</p>${teamSelect||'<button class="btn-primary" data-manager-section="team">Registrar equipo</button>'}</div><div class="pes-mini-card"><small>PRÓXIMO PARTIDO</small><h3>${esc(upcoming[0]?.awayTeam||"Calendario pendiente")}</h3><p>${upcoming[0]?.kickoff?.toDate?upcoming[0].kickoff.toDate().toLocaleDateString("es-MX"):"Sin encuentro programado"}</p></div><div class="pes-mini-card"><small>ESTADO DE LA TEMPORADA</small><h3>${esc(selected?.status||"Sin equipo")}</h3><p>${esc(selected?.category||"Categoría por definir")} · ${esc(selected?.season||"Temporada por definir")}</p></div></aside></div><div class="pes-quick-actions"><button data-manager-section="strategy">Estrategia</button><button data-manager-section="squad">Lista de jugadores</button><button data-manager-section="calendar">Avanzar en el tiempo</button><button data-manager-section="negotiations">Negociaciones</button></div>`;
 } else if(section==="team"){
  body=`<div class="pes-panel-grid"><section class="pes-glass-panel"><h3>Mi equipo</h3><p>Identidad deportiva y registro de tu club.</p><form id="manager-team-request-form" class="data-form"><label>Nombre del equipo<input name="teamName" required maxlength="100"></label><label>Municipio<input name="city" value="${esc(state.profile.city||"")}"></label><label>Rama<select name="branch"><option>Varonil</option><option>Femenil</option><option>Juvenil</option></select></label><label>Categoría<input name="category" placeholder="Libre, Sub-17..."></label><label>Temporada<input name="season" placeholder="2026-2027"></label><label>Patrocinador principal<input name="sponsorName" placeholder="Nombre del patrocinador"></label><label>Escudo del equipo (URL)<input name="crestURL" type="url" placeholder="https://..."></label><label>Logo del patrocinador (URL)<input name="sponsorLogoURL" type="url" placeholder="https://..."></label><label>Competición<select name="leagueId">${state.leagues.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join("")}</select></label><div class="wide"><button class="btn-primary">Solicitar inscripción del equipo</button></div></form></section><section class="pes-glass-panel"><h3>Equipos administrados</h3>${teams.map(t=>`<div class="pes-list-row"><b>${esc(t.name)}</b><span>${esc(t.status||"Activo")}</span></div>`).join("")||'<p class="muted">Todavía no tienes equipos registrados.</p>'}</section></div>`;
 } else if(section==="strategy"){
  body=`<section class="pes-glass-panel"><div class="pes-section-head"><div><h3>Plan táctico</h3><p>${esc(selected?.name||"Selecciona un equipo")}</p></div><span class="pes-tag">FORMACIÓN 4-3-3</span></div><div class="pes-tactics-layout"><div class="pes-pitch"><div class="pitch-box"></div><div class="pitch-mid"></div><div class="pitch-circle"></div>${[[50,12,"DC"],[27,29,"EI"],[73,29,"ED"],[38,46,"MC"],[62,46,"MC"],[50,57,"MCD"],[18,76,"LI"],[39,82,"DFC"],[61,82,"DFC"],[82,76,"LD"],[50,94,"PT"]].map(([x,y,pos],i)=>`<div class="pes-player-dot" style="left:${x}%;top:${y}%"><b>${i+1}</b><small>${pos}</small></div>`).join("")}</div><aside><h4>Indicaciones del equipo</h4><div class="pes-list-row">Estilo ofensivo <b>Contraataques rápidos</b></div><div class="pes-list-row">Presión <b>Media</b></div><div class="pes-list-row">Línea defensiva <b>Equilibrada</b></div><p class="muted">La pizarra es una vista inicial; la asignación real de jugadores a posiciones se habilitará al completar la plantilla.</p></aside></div></section>`;
 } else if(section==="squad"){
  body=`<section class="pes-glass-panel"><div class="pes-section-head"><div><h3>Lista de jugadores</h3><p>Plantilla registrada en ${esc(selected?.name||"tu equipo")}</p></div><span class="pes-tag">${roster.docs.length} JUGADORES</span></div><div class="pes-roster-table"><div class="pes-player-row pes-table-head"><b>#</b><span>POS</span><strong>JUGADOR</strong><small>ESTADO</small></div>${rosterRows||'<div class="empty-state">No hay jugadores en la plantilla. Las incorporaciones aceptadas aparecerán aquí.</div>'}</div></section>`;
 } else if(section==="calendar"){
  const days=Array.from({length:35},(_,i)=>i+1);const month=new Date().toLocaleDateString("es-MX",{month:"long",year:"numeric"});
  body=`<section class="pes-glass-panel"><div class="pes-section-head"><div><h3>Avanzar en el tiempo</h3><p>Calendario de temporada · ${month}</p></div><span class="pes-tag">TEMPORADA ${esc(selected?.season||"ACTUAL")}</span></div><div class="pes-calendar"><div class="pes-calendar-days">${["LUN","MAR","MIÉ","JUE","VIE","SÁB","DOM"].map(x=>`<b>${x}</b>`).join("")}</div><div class="pes-calendar-grid">${days.map((d,i)=>{const m=upcoming.find(x=>x.round===d);return `<div class="pes-calendar-day ${m?"has-match":""}"><b>${d}</b>${m?`<small>⚽ ${esc(m.awayTeam||m.homeTeam||"Partido")}</small>`:""}</div>`}).join("")}</div></div><div class="pes-fixture-list">${upcoming.map(m=>`<div class="pes-list-row"><b>${esc(m.homeTeam||selected?.name||"Local")} vs ${esc(m.awayTeam||"Visitante")}</b><span>${m.kickoff?.toDate?m.kickoff.toDate().toLocaleDateString("es-MX"):"Por confirmar"}</span></div>`).join("")||'<p class="muted">Aún no hay partidos programados para tu competición.</p>'}</div></section>`;
 } else if(["gazette","league-calendar","league-teams","tournament","records","stats"].includes(section)){
  const labels={gazette:"Gaceta de la competición", "league-calendar":"Calendario oficial", "league-teams":"Equipos participantes",tournament:"Información del torneo",records:"Registros de temporada",stats:"Estadísticas de partidos"};
  let content="";if(section==="gazette"){const n=await getDocs(query(collection(db,"news"),where("published","==",true),limit(20))).catch(()=>({docs:[]}));content=n.docs.map(d=>`<div class="pes-list-row"><b>${esc(d.data().title||"Comunicado")}</b><span>${d.data().createdAt?.toDate?d.data().createdAt.toDate().toLocaleDateString("es-MX"):"CASCARITA"}</span></div>`).join("")}
  else if(section==="league-calendar")content=upcoming.map(m=>`<div class="pes-list-row"><b>${esc(m.homeTeam||"Local")} vs ${esc(m.awayTeam||"Visitante")}</b><span>${m.kickoff?.toDate?m.kickoff.toDate().toLocaleString("es-MX"):"Por confirmar"}</span></div>`).join("");
  else if(section==="league-teams"&&selected?.leagueId){const ts=await getDocs(query(collection(db,"teams"),where("leagueId","==",selected.leagueId),limit(80)));content=ts.docs.map(d=>`<div class="pes-list-row"><b>${esc(d.data().name)}</b><span>${esc(d.data().city||"")}</span></div>`).join("")}
  else if(section==="tournament"&&league?.exists())content=`<div class="pes-list-row"><b>${esc(league.data().name)}</b><span>${esc(league.data().season||"")}</span></div><p>${esc(league.data().city||"")} · ${esc(league.data().branch||"")} · ${esc(league.data().category||"")}</p>`;
  body=`<section class="pes-glass-panel"><h3>${labels[section]}</h3>${content||'<div class="empty-state">La información aparecerá cuando el equipo esté inscrito en una competición y existan registros oficiales.</div>'}</section>`;
 } else if(["prospects","favorites","affiliate","negotiations","search-players","transfer-news","training"].includes(section)){
  let content="";
  if(section==="prospects"||section==="search-players"){content=players.docs.filter(d=>!selected||d.data().teamId!==selected.id).map(d=>{const x=d.data();return `<div class="pes-list-row"><div><b>${esc(x.displayName||"Jugador")}</b><small>${esc(x.position||"Posición por definir")} · ${esc(x.city||"")}</small></div><button class="btn-secondary" data-prospect="${d.id}">Contactar / invitar</button></div>`}).join("")}
  else if(section==="negotiations")content=requestRows;
  else if(section==="transfer-news"){const n=await getDocs(query(collection(db,"news"),where("published","==",true),limit(20))).catch(()=>({docs:[]}));content=n.docs.map(d=>`<div class="pes-list-row"><b>${esc(d.data().title||"Movimiento")}</b><small>${esc(d.data().body||"")}</small></div>`).join("")}
  else if(section==="training")content=`<div class="pes-training-grid"><article><b>Sesión técnica</b><span>Control y pase</span></article><article><b>Preparación física</b><span>Resistencia y velocidad</span></article><article><b>Trabajo táctico</b><span>Organización colectiva</span></article></div>`;
  else if(section==="favorites")content='<p class="muted">Todavía no has marcado prospectos como favoritos.</p>';
  else if(section==="affiliate")content='<p class="muted">Aquí podrás consultar y administrar un equipo filial cuando registres uno.</p>';
  body=`<section class="pes-glass-panel"><div class="pes-section-head"><div><h3>${title}</h3><p>Mercado y planificación deportiva</p></div></div>${content||'<div class="empty-state">No hay registros para mostrar todavía.</div>'}</section>`;
 }
 return `<div class="pes-manager"><div class="pes-manager-top"><div><span class="pes-kicker">MASTER LEAGUE · CASCARITA</span><h2>${title}</h2></div><div class="pes-team-switch">${teamSelect}</div></div>${!selected?`<section class="pes-glass-panel pes-empty-club"><div class="pes-empty-icon">⚽</div><h3>Comienza tu proyecto deportivo</h3><p>Registra tu equipo y solicita incorporarte a una competición. La administración central revisará tu solicitud.</p><button class="pes-action" data-manager-section="team">REGISTRAR MI EQUIPO</button></section>`:body}</div>`;
}
async function playerCareerPage(){
 const p=state.profile;
 const req=await getDocs(query(collection(db,"transferRequests"),where("playerUid","==",state.user.uid),limit(50))).catch(()=>({docs:[]}));
 const teams=await getDocs(query(collection(db,"teams"),where("status","==","active"),limit(80)));
 const rows=teams.docs.map(d=>{const t=d.data();return `<article class="league-card"><span class="league-tag">${esc(t.branch||"Fútbol 11")} · ${esc(t.category||"Libre")}</span><h3>${esc(t.name)}</h3><p>${esc(t.city||"")} · ${esc(t.leagueName||"Sin competición")}</p><button class="btn-secondary" data-request-team="${d.id}">Solicitar incorporación →</button></article>`}).join("");
 return `<section class="manager-hero player-hero"><div><div class="eyebrow">MI CARRERA DEPORTIVA</div><h2>${esc(p.displayName||state.user.displayName||"Jugador")}</h2><p>Tu trayectoria, tus estadísticas y las oportunidades para seguir creciendo.</p></div><div class="manager-ball">♟</div></section>
 <section class="stats"><article class="stat"><small>Equipo actual</small><strong class="career-stat">${esc(p.teamName||"Libre")}</strong><span>${esc(p.position||"Posición por definir")}</span></article><article class="stat"><small>Valoración</small><strong>${Number(p.rating||0)||"—"}</strong><span>Se mostrará cuando exista una evaluación validada</span></article><article class="stat"><small>Partidos</small><strong>${Number(p.matchesPlayed||0)}</strong><span>Registros oficiales</span></article><article class="stat"><small>Goles / asistencias</small><strong>${Number(p.goals||0)} / ${Number(p.assists||0)}</strong><span>Estadísticas registradas</span></article></section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">OPORTUNIDADES</div><h3>Buscar club</h3></div></div><p class="muted">Explora equipos activos y envía una solicitud de incorporación. El club deberá revisar y responder.</p><div class="league-grid">${rows||'<div class="empty-state">Todavía no hay equipos disponibles.</div>'}</div></section>
 <section class="panel"><div class="panel-head"><div><div class="eyebrow green">SEGUIMIENTO</div><h3>Mis solicitudes</h3></div></div>${req.docs.length?req.docs.map(d=>{const x=d.data();return `<div class="history-row"><div><b>${esc(x.teamName||"Equipo")}</b><small>${esc(x.position||"")} · ${x.createdAt?.toDate?x.createdAt.toDate().toLocaleDateString("es-MX"):"Solicitud enviada"}</small></div><span class="status-pill ${x.status==="accepted"?"good":x.status==="rejected"?"bad":""}">${x.status==="accepted"?"Aceptada":x.status==="rejected"?"Rechazada":"Pendiente"}</span></div>`}).join(""):'<div class="empty-state">Aún no has enviado solicitudes a clubes.</div>'}</section>`;
}
async function openManagedTeam(id){
 const team=await getDoc(doc(db,"teams",id));if(!team.exists())return;
 const t=team.data();if(t.managerUid!==state.user.uid&&t.createdBy!==state.user.uid&&!isAdmin()){toast("No tienes autorización para administrar este equipo.","warning");return}const snap=await getDocs(collection(db,"teams",id,"roster"));
 const host=document.getElementById("manager-team-detail");if(!host)return;
 host.innerHTML=`<section class="panel form-panel"><div class="panel-head"><div><div class="eyebrow green">GESTIÓN DE PLANTILLA</div><h3>${esc(t.name)}</h3></div></div><div class="roster-list">${snap.docs.map(d=>{const p=d.data();return `<div class="history-row"><div><b>${esc(p.displayName||p.email||"Jugador")}</b><small>${esc(p.position||"Posición por definir")} · Dorsal ${esc(p.number||"—")}</small></div><span class="status-pill good">Activo</span></div>`}).join("")||'<div class="empty-state">Esta plantilla todavía no tiene jugadores.</div>'}</div><form id="manager-add-player" class="data-form"><label>Correo de la cuenta<input name="email" type="email" required></label><label>Posición<input name="position" placeholder="Portero, defensa, medio..."></label><label>Dorsal<input name="number" type="number" min="1" max="99"></label><div class="wide"><button class="btn-primary">Agregar jugador →</button></div></form></section>`;
 const form=document.getElementById("manager-add-player");form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),email=String(f.get("email")).trim().toLowerCase();try{const us=await getDocs(query(collection(db,"users"),where("email","==",email),limit(1)));if(us.empty)throw new Error("No encontramos esa cuenta. El jugador debe registrarse primero.");const u=us.docs[0],ud=u.data();await setDoc(doc(db,"teams",id,"roster",u.id),{uid:u.id,email,displayName:ud.displayName||"",position:String(f.get("position")||""),number:Number(f.get("number")||0),status:"active",joinedAt:serverTimestamp()});await setDoc(doc(db,"players",u.id),{uid:u.id,displayName:ud.displayName||"",position:String(f.get("position")||""),teamId:id,teamName:t.name,visibility:"public",updatedAt:serverTimestamp()},{merge:true});toast("Jugador agregado a la plantilla.");openManagedTeam(id)}catch(err){toast(err.message||"No se pudo agregar al jugador.","warning")}};
}
async function createManagerTeam(e){
 e.preventDefault();const f=new FormData(e.currentTarget),leagueId=String(f.get("leagueId")||"");let leagueData={};
 try{if(leagueId){const l=await getDoc(doc(db,"leagues",leagueId));if(l.exists())leagueData={leagueId,leagueName:l.data().name}}
 await addDoc(collection(db,"teams"),{name:String(f.get("name")).trim(),city:String(f.get("city")||""),branch:String(f.get("branch")),category:String(f.get("category")||"Libre"),season:String(f.get("season")||""),...leagueData,status:"active",createdBy:state.user.uid,managerUid:state.user.uid,createdAt:serverTimestamp()});
 toast("Equipo creado. Ya puedes administrar su plantilla.");renderPage()}catch(err){console.error(err);toast("No se pudo crear el equipo. Verifica permisos de Firestore.","warning")}
}
async function inviteProspect(playerUid){try{if(!state.selectedManagerTeam)throw new Error("Primero selecciona un equipo.");const team=await getDoc(doc(db,"teams",state.selectedManagerTeam));if(!team.exists())throw new Error("Equipo no encontrado.");const player=await getDoc(doc(db,"players",playerUid));if(!player.exists())throw new Error("Perfil de jugador no encontrado.");const p=player.data();const prior=await getDocs(query(collection(db,"transferRequests"),where("playerUid","==",playerUid),where("teamId","==",state.selectedManagerTeam),where("status","==","invited"),limit(1)));if(!prior.empty)throw new Error("Ya enviaste una invitación a este jugador.");await addDoc(collection(db,"transferRequests"),{playerUid,playerName:p.displayName||"Jugador",playerEmail:p.email||"",teamId:state.selectedManagerTeam,teamName:team.data().name,managerUid:state.user.uid,status:"invited",createdAt:serverTimestamp()});toast("Invitación enviada al jugador.");renderPage()}catch(e){toast(e.message||"No se pudo enviar la invitación.","warning")}}
async function requestToJoinTeam(id){
 try{const t=await getDoc(doc(db,"teams",id));if(!t.exists())throw new Error("El equipo ya no está disponible.");const x=t.data();if(x.managerUid===state.user.uid||x.createdBy===state.user.uid)throw new Error("No puedes solicitar unirte a tu propio equipo.");const prior=await getDocs(query(collection(db,"transferRequests"),where("playerUid","==",state.user.uid),where("teamId","==",id),where("status","==","pending"),limit(1)));if(!prior.empty)throw new Error("Ya tienes una solicitud pendiente para este equipo.");await addDoc(collection(db,"transferRequests"),{playerUid:state.user.uid,playerEmail:state.user.email,playerName:state.profile.displayName||state.user.displayName||"Jugador",teamId:id,teamName:x.name,managerUid:x.managerUid||x.createdBy||"",position:state.profile.position||"",status:"pending",createdAt:serverTimestamp()});toast("Solicitud enviada al equipo.");renderPage()}catch(err){toast(err.message||"No se pudo enviar la solicitud.","warning")}
}
async function reviewTransfer(id,accepted){
 try{const r=await getDoc(doc(db,"transferRequests",id));if(!r.exists())throw new Error("Solicitud no encontrada.");const x=r.data();if(x.managerUid!==state.user.uid)throw new Error("No tienes autorización para responder.");await updateDoc(doc(db,"transferRequests",id),{status:accepted?"accepted":"rejected",reviewedBy:state.user.uid,reviewedAt:serverTimestamp()});if(accepted){const team=await getDoc(doc(db,"teams",x.teamId));if(!team.exists())throw new Error("El equipo ya no existe.");await setDoc(doc(db,"teams",x.teamId,"roster",x.playerUid),{uid:x.playerUid,email:x.playerEmail,displayName:x.playerName,position:x.position||"",status:"active",joinedAt:serverTimestamp()});await setDoc(doc(db,"players",x.playerUid),{uid:x.playerUid,displayName:x.playerName,teamId:x.teamId,teamName:team.data().name,visibility:"public",updatedAt:serverTimestamp()},{merge:true})}toast(accepted?"Solicitud aceptada y jugador incorporado.":"Solicitud rechazada.");renderPage()}catch(err){console.error(err);toast(err.message||"No se pudo procesar la solicitud.","warning")}
}

async function submitManagerTeamRequest(e){e.preventDefault();const f=new FormData(e.currentTarget),leagueId=String(f.get("leagueId")||"");try{let leagueName="";if(leagueId){const l=await getDoc(doc(db,"leagues",leagueId));if(!l.exists())throw new Error("La competición seleccionada ya no está disponible.");leagueName=l.data().name||"";}await addDoc(collection(db,"teamRequests"),{uid:state.user.uid,requesterUid:state.user.uid,managerUid:state.user.uid,managerEmail:state.user.email,teamName:String(f.get("teamName")).trim(),clubName:String(state.profile.clubName||f.get("teamName")).trim(),city:String(f.get("city")||""),branch:String(f.get("branch")||"Varonil"),category:String(f.get("category")||"Libre"),season:String(f.get("season")||""),sponsorName:String(f.get("sponsorName")||""),sponsorLogoURL:String(f.get("sponsorLogoURL")||""),crestURL:String(f.get("crestURL")||""),leagueId,leagueName,status:"pending",createdAt:serverTimestamp()});toast("Solicitud enviada a la administración.");renderPage()}catch(err){console.error(err);toast(err.message||"No se pudo enviar la solicitud. Revisa las reglas de Firestore.","warning")}}

function shellManagerNavRefresh(){if(state.activeMode==="manager"){const active=state.managerSection;document.querySelectorAll("[data-manager-section]").forEach(b=>b.classList.toggle("active",b.dataset.managerSection===active));}}
function bindPage(){
 document.querySelectorAll("[data-manager-section]").forEach(b=>b.onclick=()=>{state.managerSection=b.dataset.managerSection;localStorage.setItem("cascarita-manager-section",state.managerSection);renderPage();shellManagerNavRefresh()});
 const teamSelect=document.getElementById("manager-team-select");if(teamSelect)teamSelect.onchange=()=>{state.selectedManagerTeam=teamSelect.value;renderPage()};


 const verify=document.getElementById("send-verify");if(verify)verify.onclick=async()=>{try{await sendEmailVerification(state.user);toast("Correo de verificación enviado.")}catch(e){toast("No se pudo enviar el correo de verificación.","warning")}};
 const claim=document.getElementById("claim-founder");if(claim)claim.onclick=async()=>{claim.disabled=true;try{await auth.currentUser.reload();if(!auth.currentUser.emailVerified)throw new Error("La cuenta fundadora debe verificar el correo para activar la superadministración.");await auth.currentUser.getIdToken(true);const result=await httpsCallable(functions,"claimFounderSuperadmin")();await auth.currentUser.getIdToken(true);toast(result.data?.message||"Superadministración activada.");location.reload()}catch(e){toast(e.message||"No se pudo activar la superadministración.","warning");claim.disabled=false}};
 const go=document.querySelector("[data-go]");if(go)go.onclick=()=>{state.page=go.dataset.go;renderPage()};document.querySelectorAll("[data-league]").forEach(b=>b.onclick=()=>showLeague(b.dataset.league));
 const pf=document.getElementById("profile-form");if(pf)pf.onsubmit=saveProfile;const photo=document.getElementById("profile-photo");if(photo)photo.onchange=uploadPhoto;
 const lf=document.getElementById("league-form");if(lf)lf.onsubmit=saveLeague;const reset=document.getElementById("league-form-reset");if(reset)reset.onclick=()=>{lf.reset();lf.elements.leagueId.value="";document.getElementById("league-form-title").textContent="Crear competición"};
 const nf=document.getElementById("news-form");if(nf)nf.onsubmit=createNews;
 document.querySelectorAll("[data-approve-role]").forEach(b=>b.onclick=()=>approveRole(b.dataset.approveRole));
 document.querySelectorAll("[data-edit-league]").forEach(b=>b.onclick=()=>editLeague(b.dataset.editLeague));
 document.querySelectorAll("[data-league-status]").forEach(b=>b.onclick=()=>changeLeagueStatus(b.dataset.leagueStatus,b.dataset.status));
 document.querySelectorAll("[data-delete-league]").forEach(b=>b.onclick=()=>deleteLeague(b.dataset.deleteLeague));
 document.querySelectorAll("[data-fixtures]").forEach(b=>b.onclick=()=>generateFixtures(b.dataset.fixtures));
 document.querySelectorAll("[data-team-approve]").forEach(b=>b.onclick=()=>reviewTeamRequest(b.dataset.teamApprove,'approved'));
 document.querySelectorAll("[data-team-reject]").forEach(b=>b.onclick=()=>reviewTeamRequest(b.dataset.teamReject,'rejected'));
 document.querySelectorAll("[data-user-status]").forEach(b=>b.onclick=()=>setUserStatus(b.dataset.userStatus,b.dataset.status));
 document.querySelectorAll("[data-generic-request]").forEach(b=>b.onclick=()=>reviewGenericRequest(b.dataset.genericRequest,b.dataset.kind));
 const search=document.getElementById('user-search');if(search)search.oninput=()=>{const q=search.value.toLowerCase();document.querySelectorAll('#user-directory .history-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))};
 document.querySelectorAll("[data-role-panel]").forEach(b=>b.onclick=()=>{const host=document.getElementById("role-panel-detail");host.innerHTML=`<div class="notice-soft"><b>${esc(b.dataset.rolePanel)}:</b> tu panel está habilitado. Las herramientas específicas se irán incorporando conectadas a los datos y permisos de tu perfil.</div>`});const trf=document.getElementById("team-request-form");if(trf)trf.onsubmit=submitManagerTeamRequest;const mtrf=document.getElementById("manager-team-request-form");if(mtrf)mtrf.onsubmit=submitManagerTeamRequest;document.querySelectorAll("[data-prospect]").forEach(b=>b.onclick=()=>inviteProspect(b.dataset.prospect));document.querySelectorAll("[data-manage-team]").forEach(b=>b.onclick=()=>openManagedTeam(b.dataset.manageTeam));document.querySelectorAll("[data-request-team]").forEach(b=>b.onclick=()=>requestToJoinTeam(b.dataset.requestTeam));document.querySelectorAll("[data-transfer-approve]").forEach(b=>b.onclick=()=>reviewTransfer(b.dataset.transferApprove,true));document.querySelectorAll("[data-transfer-reject]").forEach(b=>b.onclick=()=>reviewTransfer(b.dataset.transferReject,false));
}
async function saveProfile(e){e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get("displayName")).trim();try{await updateDoc(doc(db,"users",state.user.uid),{displayName:name,phone:String(f.get("phone")||""),city:String(f.get("city")||""),bio:String(f.get("bio")||""),updatedAt:serverTimestamp()});await updateProfile(state.user,{displayName:name});state.profile={...state.profile,displayName:name,phone:f.get("phone"),city:f.get("city"),bio:f.get("bio")};if(roleList().includes("Jugador")){const playerPosition=String(f.get("playerPosition")||"").trim(),playerVisibility=String(f.get("playerVisibility")||"public");await setDoc(doc(db,"players",state.user.uid),{uid:state.user.uid,displayName:name,position:playerPosition,city:String(f.get("city")||""),visibility:playerVisibility,updatedAt:serverTimestamp()},{merge:true});state.profile.playerPosition=playerPosition;state.profile.playerVisibility=playerVisibility;}toast("Perfil actualizado.");renderPage()}catch(e){console.error(e);toast("No se pudo guardar. Revisa las reglas de Firestore.","warning")}}
async function uploadPhoto(e){const file=e.target.files?.[0];if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>5*1024*1024){toast("Elige JPG, PNG o WEBP de máximo 5 MB.","warning");return}try{const path=`profilePhotos/${state.user.uid}/avatar-${Date.now()}`;const r=storageRef(storage,path);await uploadBytes(r,file,{contentType:file.type});const url=await getDownloadURL(r);await updateDoc(doc(db,"users",state.user.uid),{photoURL:url,photoPath:path,updatedAt:serverTimestamp()});state.profile.photoURL=url;toast("Fotografía actualizada.");renderPage()}catch(err){console.error(err);toast("No se pudo subir la foto. Revisa Storage Rules.","warning")}}
async function saveLeague(e){e.preventDefault();const f=new FormData(e.currentTarget),payload={leagueId:String(f.get('leagueId')||''),name:String(f.get('name')).trim(),season:String(f.get('season')).trim(),city:String(f.get('city')).trim(),branch:String(f.get('branch')),category:String(f.get('category')||'').trim(),modality:String(f.get('modality')),format:String(f.get('format')),teamLimit:Number(f.get('teamLimit')),legs:Number(f.get('legs')),status:String(f.get('status')),pointsWin:Number(f.get('pointsWin')),pointsDraw:Number(f.get('pointsDraw')),pointsLoss:Number(f.get('pointsLoss')),tieBreakers:String(f.get('tieBreakers')||'Puntos, diferencia de goles, goles a favor').trim()};try{await httpsCallable(functions,'adminSaveLeague')(payload);toast('Competición guardada.');renderPage()}catch(err){console.error(err);toast(err.message||'No se pudo guardar la competición.','warning')}}
async function editLeague(id){try{const snap=await getDoc(doc(db,'leagues',id));if(!snap.exists())throw new Error('Competición no encontrada');const x=snap.data(),f=document.getElementById('league-form');for(const k of ['name','season','city','branch','category','modality','format','teamLimit','legs','status','pointsWin','pointsDraw','pointsLoss','tieBreakers'])if(f.elements[k])f.elements[k].value=x[k]??({teamLimit:16,legs:2,pointsWin:3,pointsDraw:1,pointsLoss:0}[k]??'');f.elements.leagueId.value=id;document.getElementById('league-form-title').textContent='Editar competición';f.scrollIntoView({behavior:'smooth',block:'center'})}catch(e){toast(e.message,'warning')}}
async function changeLeagueStatus(id,status){try{await httpsCallable(functions,'adminSaveLeague')({leagueId:id,status});toast('Estado de competición actualizado.');renderPage()}catch(e){toast(e.message||'No se pudo actualizar.','warning')}}
async function deleteLeague(id){if(!confirm('¿Eliminar esta competición? Solo se permitirá si no tiene equipos ni partidos.'))return;try{await httpsCallable(functions,'adminDeleteLeague')({leagueId:id});toast('Competición eliminada.');renderPage()}catch(e){toast(e.message||'No se pudo eliminar.','warning')}}
async function generateFixtures(id){if(!confirm('Se generará el calendario automáticamente con los equipos aprobados. No se puede repetir si ya existen encuentros. ¿Continuar?'))return;try{const r=await httpsCallable(functions,'generateLeagueFixtures')({leagueId:id});toast(r.data?.message||'Calendario generado.');renderPage()}catch(e){console.error(e);toast(e.message||'No se pudo generar el calendario.','warning')}}
async function reviewTeamRequest(id,status){try{const r=await httpsCallable(functions,'reviewTeamRequest')({requestId:id,status});toast(r.data?.message||'Solicitud procesada.');renderPage()}catch(e){console.error(e);toast(e.message||'No se pudo procesar la solicitud.','warning')}}
async function setUserStatus(uid,status){if(!confirm(status==='suspended'?'¿Suspender el acceso de esta cuenta?':status==='deactivated'?'¿Dar de baja esta cuenta?':'¿Reactivar esta cuenta?'))return;try{await httpsCallable(functions,'setUserAccessStatus')({uid,status});toast('Acceso actualizado.');renderPage()}catch(e){toast(e.message||'No se pudo cambiar el acceso.','warning')}}
async function reviewGenericRequest(id,kind){const status=confirm('¿Aprobar esta solicitud?')?'approved':'rejected';try{await httpsCallable(functions,'reviewOrganizationRequest')({requestId:id,kind,status});toast('Solicitud revisada.');renderPage()}catch(e){toast(e.message||'No se pudo revisar.','warning')}}
async function createTeamRequest(e){e.preventDefault();const f=new FormData(e.currentTarget),leagueId=String(f.get("leagueId")),league=await getDoc(doc(db,"leagues",leagueId));if(!league.exists()){toast("La competición ya no está disponible.","warning");return}try{await addDoc(collection(db,"teamRequests"),{uid:state.user.uid,email:state.user.email,name:state.profile.displayName||state.user.displayName||"",teamName:String(f.get("teamName")).trim(),clubName:String(f.get("clubName")).trim(),city:String(f.get("city")).trim(),branch:String(f.get("branch")),category:String(f.get("category")||"").trim(),leagueId,leagueName:league.data().name,status:"pending",createdAt:serverTimestamp()});toast("Solicitud enviada a la administración.");renderPage()}catch(err){console.error(err);toast(err.message||"No se pudo enviar la solicitud.","warning")}}
async function createNews(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await addDoc(collection(db,"news"),{title:String(f.get("title")).trim(),body:String(f.get("body")).trim(),published:true,authorUid:state.user.uid,createdAt:serverTimestamp()});toast("Noticia publicada.");renderPage()}catch(err){console.error(err);toast("No se pudo publicar la noticia.","warning")}}
async function approveRole(id){try{await httpsCallable(functions,"reviewRoleRequest")({requestId:id,status:"approved"});toast("Rol aprobado.");renderPage()}catch(e){console.error(e);toast(e.message||"No se pudo aprobar el rol.","warning")}}

async function showLeague(id){const l=state.leagues.find(x=>x.id===id);if(!l)return;const [teams,matches]=await Promise.all([getDocs(query(collection(db,"teams"),where("leagueId","==",id))),getDocs(query(collection(db,"matches"),where("leagueId","==",id)))]);const host=document.getElementById("league-detail");if(!host)return;const standings={};teams.forEach(d=>standings[d.id]={name:d.data().name,pj:0,pg:0,pe:0,pp:0,gf:0,gc:0,pts:0});matches.forEach(d=>{const m=d.data();if(m.status!=="final"||m.homeGoals==null||m.awayGoals==null||!standings[m.homeTeamId]||!standings[m.awayTeamId])return;const h=standings[m.homeTeamId],a=standings[m.awayTeamId];h.pj++;a.pj++;h.gf+=m.homeGoals;h.gc+=m.awayGoals;a.gf+=m.awayGoals;a.gc+=m.homeGoals;if(m.homeGoals>m.awayGoals){h.pg++;h.pts+=3;a.pp++}else if(m.homeGoals<m.awayGoals){a.pg++;a.pts+=3;h.pp++}else{h.pe++;a.pe++;h.pts++;a.pts++}});const table=Object.values(standings).sort((a,b)=>b.pts-a.pts||(b.gf-b.gc)-(a.gf-a.gc)||b.gf-a.gf);host.innerHTML=`<section class="panel"><div class="eyebrow green">${esc(l.season||"")}</div><h2>${esc(l.name)}</h2><p>${esc(l.city||"")} · ${esc(l.branch||"")}</p><h3>Tabla de posiciones</h3>${table.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>Equipo</th><th>PJ</th><th>PG</th><th>PE</th><th>PP</th><th>GF</th><th>GC</th><th>PTS</th></tr></thead><tbody>${table.map((t,i)=>`<tr><td>${i+1}</td><td>${esc(t.name)}</td><td>${t.pj}</td><td>${t.pg}</td><td>${t.pe}</td><td>${t.pp}</td><td>${t.gf}</td><td>${t.gc}</td><td><b>${t.pts}</b></td></tr>`).join("")}</tbody></table></div>`:'<div class="empty-state">La tabla se calculará conforme se registren equipos y resultados validados.</div>'}<h3>Equipos participantes</h3>${teams.empty?'<div class="empty-state">Todavía no hay equipos inscritos.</div>':teams.docs.map(d=>`<div class="history-row"><b>${esc(d.data().name)}</b><small>${esc(d.data().branch||"")}</small></div>`).join("")}<h3>Encuentros</h3>${matches.empty?'<div class="empty-state">Todavía no hay encuentros programados.</div>':matches.docs.map(d=>{const m=d.data();return `<div class="history-row"><div><b>${esc(m.homeTeam)} vs ${esc(m.awayTeam)}</b><small>${m.kickoff?.toDate?m.kickoff.toDate().toLocaleString("es-MX"):"Fecha por confirmar"}</small></div><strong>${m.status==="final"?`${m.homeGoals} - ${m.awayGoals}`:"Programado"}</strong></div>`}).join("")}</section>`}

onAuthStateChanged(auth,async user=>{state.user=user;if(!user){state.admin=false;state.profile={};state.activeMode="public";authView();return}try{const token=await getIdTokenResult(user,true);state.claims=token.claims;state.admin=token.claims.superadmin===true;const ref=doc(db,"users",user.uid),snap=await getDoc(ref);if(!snap.exists()){await setDoc(ref,{displayName:user.displayName||"",email:user.email||"",roles:[state.pendingInitialRole||"Aficionado"],status:"active",createdAt:serverTimestamp(),updatedAt:serverTimestamp()});state.profile={displayName:user.displayName||"",email:user.email,roles:[state.pendingInitialRole||"Aficionado"]}}else state.profile=snap.data();if(!Array.isArray(state.profile.roles))state.profile.roles=["Aficionado"];const roles=state.profile.roles;state.activeMode=state.admin?"admin":roles.some(r=>["Directivo","Administrador de club"].includes(r))?"manager":roles.includes("Jugador")?"player":"public";state.page=state.activeMode==="admin"?"Administración":state.activeMode==="manager"?"Modo manager":state.activeMode==="player"?"Modo jugador":"Inicio";localStorage.setItem("cascarita-active-mode",state.activeMode);shell();renderPage()}catch(e){console.error(e);toast("No se pudo cargar tu perfil o tus permisos.","warning");shell()}});
